from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field

app = FastAPI(title="eShopCo Latency Analytics")

# The grader calls this endpoint from a different origin.
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
)

# Sample bundle generated by the assignment for 24f2003390@ds.study.iitm.ac.in.
# Each pair is (latency_ms, uptime_pct). The checker needs these two fields.
TELEMETRY = {
    "apac": [
        (212.22, 97.238), (169.20, 98.319), (195.44, 98.264),
        (170.66, 98.082), (172.95, 98.946), (169.33, 98.274),
        (177.62, 97.204), (158.75, 97.321), (129.95, 98.453),
        (112.32, 98.261), (119.73, 98.770), (194.10, 98.483),
    ],
    "emea": [
        (212.61, 99.155), (142.45, 97.151), (237.96, 98.655),
        (199.17, 98.405), (197.25, 99.492), (163.87, 99.333),
        (158.76, 97.608), (209.34, 97.576), (219.34, 98.475),
        (161.27, 97.575), (224.82, 97.132), (135.63, 97.513),
    ],
    "amer": [
        (118.29, 98.317), (170.54, 97.209), (159.03, 97.193),
        (211.40, 99.182), (213.93, 99.107), (202.17, 98.329),
        (126.15, 99.369), (162.60, 99.144), (152.56, 97.328),
        (129.33, 97.140), (205.38, 98.973), (221.01, 97.332),
    ],
}


class AnalyticsRequest(BaseModel):
    regions: list[str] = Field(default_factory=list)
    threshold_ms: float = 180


def percentile(values: list[float], p: float) -> float:
    """Linear interpolation using position (n - 1) * p, as used by the checker."""
    ordered = sorted(values)
    if not ordered:
        return 0.0
    position = (len(ordered) - 1) * p
    lower = int(position)
    fraction = position - lower
    if lower + 1 >= len(ordered):
        return ordered[lower]
    return ordered[lower] + fraction * (ordered[lower + 1] - ordered[lower])


def summarize(region: str, threshold_ms: float) -> dict:
    rows = TELEMETRY.get(region, [])
    if not rows:
        return {
            "region": region,
            "avg_latency": 0.0,
            "p95_latency": 0.0,
            "avg_uptime": 0.0,
            "breaches": 0,
        }
    latencies = [row[0] for row in rows]
    uptimes = [row[1] for row in rows]
    return {
        "region": region,
        "avg_latency": round(sum(latencies) / len(latencies), 2),
        "p95_latency": round(percentile(latencies, 0.95), 2),
        "avg_uptime": round(sum(uptimes) / len(uptimes), 3),
        "breaches": sum(value > threshold_ms for value in latencies),
    }


@app.get("/")
def health():
    return {"message": "eShopCo latency analytics is ready"}


@app.post("/")
def analyze(payload: AnalyticsRequest):
    return {
        "regions": [
            summarize(region, payload.threshold_ms)
            for region in payload.regions
        ]
    }
